[tool:write] input: {
  "content": "import {
  addToScene,
  createMeshFromData,
  createShaderMaterial,
  removeFromScene,
  setSubtreeVisible,
  type EngineContext,
  type Mesh,
  type SceneContext,
  type ShaderMaterial,
} from "@babylonjs/lite";

import type { World } from "../core/world.js";
import type { BlockAtlas } from "./atlas.js";
import { meshChunk, type MeshGeometry } from "./mesher.js";
import {
  createVoxelMaterial,
  type VoxelMaterialOptions,
} from "./voxel-material.js";
import { CHUNK_SX, CHUNK_SZ, chunkKey } from "../core/constants.js";

interface ChunkMeshes {
  meshes: Mesh[];
}

export interface ChunkRendererOptions extends VoxelMaterialOptions {
  radius: number;
  budgetPerFrame?: number;
}

export class ChunkRenderer {
  private readonly engine: EngineContext;
  private readonly scene: SceneContext;
  private readonly world: World;
  private readonly atlas: BlockAtlas;
  private readonly radius: number;
  private readonly budget: number;

  private readonly matOpaque: ShaderMaterial;
  private readonly matCutout: ShaderMaterial;
  private readonly matBlend: ShaderMaterial;

  private readonly active = new Map<string, ChunkMeshes>();
  private readonly pending: { cx: number; cz: number; dist: number }[] = [];
  private readonly graveyard: { meshes: Mesh[]; ttl: number }[] = [];
  private counter = 0;

  constructor(
    engine: EngineContext,
    scene: SceneContext,
    world: World,
    atlas: BlockAtlas,
    opts: ChunkRendererOptions,
  ) {
    this.engine = engine;
    this.scene = scene;
    this.world = world;
    this.atlas = atlas;
    this.radius = opts.radius;
    this.budget = opts.budgetPerFrame ?? 3;

    this.matOpaque = createVoxelMaterial("opaque", atlas.texture, "opaque", opts);
    this.matCutout = createVoxelMaterial("cutout", atlas.texture, "cutout", opts);
    this.matBlend = createVoxelMaterial("blend", atlas.texture, "blend", {
      ...opts,
      alpha: 0.72,
    });
  }

  update(centerWx: number, centerWz: number): void {
    const ccx = Math.floor(centerWx / CHUNK_SX);
    const ccz = Math.floor(centerWz / CHUNK_SZ);
    const keep = this.radius + 1;

    for (const [key] of this.active) {
      const parts = key.split(",");
      const cx = Number(parts[0]);
      const cz = Number(parts[1]);
      if (Math.abs(cx - ccx) > keep || Math.abs(cz - ccz) > keep) {
        this.retire(this.active.get(key)!.meshes);
        this.active.delete(key);
        this.world.dropChunk(cx, cz);
      }
    }

    this.pending.length = 0;
    for (let dz = -this.radius; dz <= this.radius; dz++) {
      for (let dx = -this.radius; dx <= this.radius; dx++) {
        const cx = ccx + dx;
        const cz = ccz + dz;
        if (this.active.has(chunkKey(cx, cz))) continue;
        this.pending.push({ cx, cz, dist: dx * dx + dz * dz });
      }
    }
    this.pending.sort((a, b) => a.dist - b.dist);
  }

  processQueue(): void {
    this.drainGraveyard();
    let done = 0;
    while (done < this.budget && this.pending.length > 0) {
      const next = this.pending.shift()!;
      if (this.active.has(chunkKey(next.cx, next.cz))) continue;
      this.buildChunk(next.cx, next.cz);
      done++;
    }
  }

  remeshEdit(wx: number, wz: number): void {
    const cx = Math.floor(wx / CHUNK_SX);
    const cz = Math.floor(wz / CHUNK_SZ);
    const lx = ((wx % CHUNK_SX) + CHUNK_SX) % CHUNK_SX;
    const lz = ((wz % CHUNK_SZ) + CHUNK_SZ) % CHUNK_SZ;
    const nx = lx === 0 ? -1 : lx === CHUNK_SX - 1 ? 1 : 0;
    const nz = lz === 0 ? -1 : lz === CHUNK_SZ - 1 ? 1 : 0;
    this.remeshIfActive(cx, cz);
    if (nx) this.remeshIfActive(cx + nx, cz);
    if (nz) this.remeshIfActive(cx, cz + nz);
  }

  reset(): void {
    for (const cm of this.active.values()) this.retire(cm.meshes);
    this.active.clear();
    this.pending.length = 0;
  }

  get activeCount(): number {
    return this.active.size;
  }

  private remeshIfActive(cx: number, cz: number): void {
    const key = chunkKey(cx, cz);
    if (!this.active.has(key)) return;
    this.retire(this.active.get(key)!.meshes);
    this.active.delete(key);
    this.buildChunk(cx, cz);
  }

  private retire(meshes: Mesh[]): void {
    for (const m of meshes) setSubtreeVisible(m, false);
    this.graveyard.push({ meshes, ttl: 3 });
  }

  private drainGraveyard(): void {
    for (let i = this.graveyard.length - 1; i >= 0; i--) {
      if (--this.graveyard[i]!.ttl > 0) continue;
      for (const m of this.graveyard[i]!.meshes) removeFromScene(this.scene, m);
      this.graveyard.splice(i, 1);
    }
  }

  private buildChunk(cx: number, cz: number): void {
    const data = meshChunk(this.world, cx, cz, this.atlas);
    const meshes: Mesh[] = [];

    const add = (geo: MeshGeometry | null, mat: ShaderMaterial, tag: string, order: number) => {
      if (!geo) return;
      const mesh = createMeshFromData(
        this.engine, `chunk_${tag}_${this.counter++}`,
        geo.positions, geo.normals, geo.indices, geo.uvs,
        undefined, undefined, geo.colors,
      );
      mesh.material = mat;
      mesh.renderOrder = order;
      addToScene(this.scene, mesh);
      meshes.push(mesh);
    };

    add(data.opaque, this.matOpaque, "op", 0);
    add(data.cutout, this.matCutout, "ct", 1);
    add(data.blend, this.matBlend, "bl", 1000);

    this.active.set(chunkKey(cx, cz), { meshes });
  }

  dispose(): void {
    this.drainGraveyard();
    for (const e of this.graveyard) for (const m of e.meshes) removeFromScene(this.scene, m);
    this.graveyard.length = 0;
    for (const cm of this.active.values()) for (const m of cm.meshes) removeFromScene(this.scene, m);
    this.active.clear();
  }
}
